class Solution {
public:
    int reachableNodes(int n, std::vector<std::vector<int>>& edges, std::vector<int>& restricted) {
        std::unordered_set<int> bad(restricted.begin(), restricted.end());
        std::vector<std::vector<int>> adj(n);
        for (const auto& e : edges) {
            if (!bad.count(e[0]) && !bad.count(e[1])) {
                adj[e[0]].push_back(e[1]);
                adj[e[1]].push_back(e[0]);
            }
        }
        std::vector<bool> visited(n, false);
        std::queue<int> q;
        q.push(0);
        visited[0] = true;
        int ans = 0;
        while (!q.empty()) {
            int u = q.front();
            q.pop();
            ans++;
            for (int v : adj[u]) {
                if (!visited[v]) {
                    visited[v] = true;
                    q.push(v);
                }
            }
        }
        return ans;
    }
};

class Solution {
    public int reachableNodes(int n, int[][] edges, int[] restricted) {
        java.util.Set<Integer> bad = new java.util.HashSet<>();
        for (int r : restricted) bad.add(r);
        java.util.List<Integer>[] adj = new java.util.ArrayList[n];
        for (int i = 0; i < n; ++i) adj[i] = new java.util.ArrayList<>();
        for (int[] e : edges) {
            if (!bad.contains(e[0]) && !bad.contains(e[1])) {
                adj[e[0]].add(e[1]);
                adj[e[1]].add(e[0]);
            }
        }
        boolean[] visited = new boolean[n];
        java.util.Queue<Integer> q = new java.util.LinkedList<>();
        q.add(0);
        visited[0] = true;
        int ans = 0;
        while (!q.isEmpty()) {
            int u = q.poll();
            ans++;
            for (int v : adj[u]) {
                if (!visited[v]) {
                    visited[v] = true;
                    q.add(v);
                }
            }
        }
        return ans;
    }
}

